package handlers.skill.effects;

import org.l2jmobius.gameserver.config.PlayerConfig;
import org.l2jmobius.gameserver.entity.actor.Creature;
import org.l2jmobius.gameserver.entity.item.enums.ShotType;
import org.l2jmobius.gameserver.entity.item.instance.Item;
import org.l2jmobius.gameserver.mechanics.effects.AbstractEffect;
import org.l2jmobius.gameserver.mechanics.effects.EffectType;
import org.l2jmobius.gameserver.mechanics.skill.Skill;
import org.l2jmobius.gameserver.mechanics.stats.Formulas;
import org.l2jmobius.gameserver.util.StatSet;

/**
 * Handles the application of magical damage caused by an abnormal effect.<br>
 * This class manages how {@code MagicalDamageByAbnormal} interacts with targets.
 * @author Adry_85
 */
public class MagicalDamageByAbnormal extends AbstractEffect
{
	private final double _power;
	
	/**
	 * Creates a new instance of {@code MagicalDamageByAbnormal}.<br>
	 * It initializes the effect using values from a {@code StatSet}.<br>
	 * This constructor expects a {@code power} value to be present.
	 * @param params The {@code StatSet} containing the configuration data.
	 */
	public MagicalDamageByAbnormal(StatSet params)
	{
		_power = params.getDouble("power", 0);
		
		if (params.contains("amount"))
		{
			throw new IllegalArgumentException(getClass().getSimpleName() + " should use power instead of amount.");
		}
	}
	
	/**
	 * Determines if the effect successfully hits the target.<br>
	 * This method checks if the {@code effected} creature fails to evade the attack.<br>
	 * It returns {@code true} if the hit is successful and {@code false} otherwise.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the effect.
	 * @param skill The {@code Skill} being used.
	 * @return {@code true} if the attack hits, {@code false} if it is evaded.
	 */
	@Override
	public boolean calcSuccess(Creature effector, Creature effected, Skill skill)
	{
		return !Formulas.calcSkillEvasion(effector, effected, skill);
	}
	
	/**
	 * Retrieves the type of effect associated with this instance.<br>
	 * This method returns a constant value from {@code EffectType}.
	 * @return The {@code EffectType} for this effect.
	 */
	@Override
	public EffectType getEffectType()
	{
		return EffectType.MAGICAL_ATTACK;
	}
	
	/**
	 * Checks if this effect occurs instantly.<br>
	 * This method always returns {@code true}.
	 * @return {@code true} if the effect is instant.
	 */
	@Override
	public boolean isInstant()
	{
		return true;
	}
	
	/**
	 * Applies the instant damage effect of a skill.<br>
	 * This method calculates magic damage based on the provided parameters.<br>
	 * It also handles specific logic for fake death and spirit shots.
	 * @param effector The creature performing the action.
	 * @param effected The creature receiving the damage.
	 * @param skill The {@code Skill} being executed.
	 * @param item The {@code Item} used to trigger the effect.
	 */
	@Override
	public void instant(Creature effector, Creature effected, Skill skill, Item item)
	{
		if (effector.isAlikeDead())
		{
			return;
		}
		
		if (effected.isPlayer() && effected.asPlayer().isFakeDeath() && PlayerConfig.FAKE_DEATH_DAMAGE_STAND)
		{
			effected.stopFakeDeath(true);
		}
		
		final boolean sps = skill.useSpiritShot() && effector.isChargedShot(ShotType.SPIRITSHOTS);
		final boolean bss = skill.useSpiritShot() && effector.isChargedShot(ShotType.BLESSED_SPIRITSHOTS);
		final boolean mcrit = Formulas.calcCrit(skill.getMagicCriticalRate(), effector, effected, skill);
		double damage = Formulas.calcMagicDam(effector, effected, skill, effector.getMAtk(), _power, effected.getMDef(), sps, bss, mcrit);
		
		// each buff increase +30%
		damage *= (((effected.getBuffCount() * 0.3) + 1.3) / 4);
		
		effector.doAttack(damage, effected, skill, false, false, mcrit, false);
	}
}
